head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > download]<br/>서버에서 파일을 다운로드합니다.",
    "validation" : [
        "action(필수) 파라미터로 파일 다운로드 기능이 구현된 서버 URL 을 설정할 수 있어야 합니다.",
        "requestData(선택) 파라미터로 서버로 전송할 데이터 문자열을 설정할 수 있어야 합니다 (서버에서 'xmlValue' 이름으로 수신).",
        "sendMethod(선택) 파라미터로 HTTP 전송 방식 'get' / 'post' 를 설정할 수 있어야 합니다.",
        "isXhr(선택) 파라미터를 true 로 설정하면 XHR 방식(Content-Type=text/plain) 으로, false(기본값) 로 설정하면 IFrame+Form 방식으로 다운로드가 수행되어야 합니다.",
        "sendMethod='get' 으로 설정하면 action URL 의 기존 Query 문자열은 무시되며 xmlValue 가 할당되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// XHR 패치 관련 플래그
scwin.xhrCaptured = null;
scwin.originalXhrOpen = null;
scwin.originalXhrSend = null;
scwin.originalXhrSetRequestHeader = null;

// XHR.open / send / setRequestHeader 패치로 호출 캡처
scwin.patchXhr = function () {
    scwin.xhrCaptured = {
        "method" : null,
        "url" : null,
        "body" : null,
        "headers" : []
    };

    if (scwin.originalXhrOpen === null) {
        scwin.originalXhrOpen = XMLHttpRequest.prototype.open;
    }
    if (scwin.originalXhrSend === null) {
        scwin.originalXhrSend = XMLHttpRequest.prototype.send;
    }
    if (scwin.originalXhrSetRequestHeader === null) {
        scwin.originalXhrSetRequestHeader = XMLHttpRequest.prototype.setRequestHeader;
    }

    XMLHttpRequest.prototype.open = function (method, url) {
        scwin.xhrCaptured.method = method;
        scwin.xhrCaptured.url = url;
        return scwin.originalXhrOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function (body) {
        scwin.xhrCaptured.body = body;
        return scwin.originalXhrSend.apply(this, arguments);
    };
    XMLHttpRequest.prototype.setRequestHeader = function (name, value) {
        scwin.xhrCaptured.headers.push({"name" : name, "value" : value});
        return scwin.originalXhrSetRequestHeader.apply(this, arguments);
    };
};

scwin.restoreXhr = function () {
    if (scwin.originalXhrOpen !== null) {
        XMLHttpRequest.prototype.open = scwin.originalXhrOpen;
    }
    if (scwin.originalXhrSend !== null) {
        XMLHttpRequest.prototype.send = scwin.originalXhrSend;
    }
    if (scwin.originalXhrSetRequestHeader !== null) {
        XMLHttpRequest.prototype.setRequestHeader = scwin.originalXhrSetRequestHeader;
    }
};



// 엔진 내부에서 form 은 생성 즉시 submit 후 DOM 에서 제거되므로, HTMLFormElement.prototype.submit 을 패치하여 submit 시점에 form 상태를 캡처
scwin.capturedForm = null;
scwin.originalFormSubmit = null;

scwin.patchFormSubmit = function () {
    scwin.capturedForm = null;
    if (scwin.originalFormSubmit === null) {
        scwin.originalFormSubmit = HTMLFormElement.prototype.submit;
    }
    HTMLFormElement.prototype.submit = function () {
        try {
            var action = this.getAttribute("action") || "";
            if (action.indexOf("$p_download_sample") > -1) {
                var xmlInput = this.querySelector("input[name='xmlValue']");
                scwin.capturedForm = {
                    action : action,
                    method : (this.getAttribute("method") || "").toLowerCase(),
                    target : this.getAttribute("target") || "",
                    xmlValue : xmlInput ? xmlInput.value : null,
                    hasXmlInput : (xmlInput !== null)
                };
            }
        } catch (e) {}
        // 실제 submit 은 호출하지 않음 (테스트 환경에서 iframe 로 실제 다운로드되는 부작용 방지)
    };
};

scwin.restoreFormSubmit = function () {
    if (scwin.originalFormSubmit !== null) {
        HTMLFormElement.prototype.submit = scwin.originalFormSubmit;
    }
};



scwin.btn_download_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 기본 호출 (action 만)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 기본 호출 (action 만) ──");
        scwin.patchFormSubmit();
        $p.download("/data/$p_download_sample.txt");

        $p.setTimeout(function () {
            scwin.restoreFormSubmit();
            var cap = scwin.capturedForm;
            if (cap) {
                wf_body_bottom.getObj("scwin").setReturnValue("생성된 form action : '" + cap.action + "'");
                wf_body_bottom.getObj("scwin").setReturnValue("생성된 form method : '" + cap.method + "'");
            } else {
                wf_body_bottom.getObj("scwin").setReturnValue("form submit 미캡처");
            }
        }, "chk_download_1", 100);
    } else if (scenario === "2") {
        // 시나리오 2 : requestData + POST (form 내 xmlValue hidden input 확인)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : requestData + POST ──");
        scwin.patchFormSubmit();
        $p.download("/data/$p_download_sample.txt", "K00001");

        $p.setTimeout(function () {
            scwin.restoreFormSubmit();
            var cap = scwin.capturedForm;
            if (cap) {
                wf_body_bottom.getObj("scwin").setReturnValue("form method : '" + cap.method + "' / xmlValue input.value : '" + cap.xmlValue + "'");
                wf_body_bottom.getObj("scwin").setReturnValue("[검증] xmlValue=K00001 일치 여부 : " + (cap.xmlValue === "K00001"));
            } else {
                wf_body_bottom.getObj("scwin").setReturnValue("form submit 미캡처");
            }
        }, "chk_download_2", 100);
    } else if (scenario === "3") {
        // 시나리오 3 : sendMethod='get' (form method 및 xmlValue input 확인)
        // ※ form method='get' 으로 submit 되면 브라우저가 xmlValue 를 URL query 로 변환하여 전송
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : sendMethod='get' ──");
        scwin.patchFormSubmit();
        $p.download("/data/$p_download_sample.txt", "K00001", "get");

        $p.setTimeout(function () {
            scwin.restoreFormSubmit();
            var cap = scwin.capturedForm;
            if (cap) {
                wf_body_bottom.getObj("scwin").setReturnValue("form action : '" + cap.action + "' / method : '" + cap.method + "'");
                wf_body_bottom.getObj("scwin").setReturnValue("xmlValue input.value : '" + cap.xmlValue + "'");
                wf_body_bottom.getObj("scwin").setReturnValue("[검증] method='get' + xmlValue=K00001 : " + (cap.method === "get" && cap.xmlValue === "K00001"));
            } else {
                wf_body_bottom.getObj("scwin").setReturnValue("form submit 미캡처");
            }
        }, "chk_download_3", 100);
    } else if (scenario === "4") {
        // 시나리오 4 : isXhr=true (XHR 방식)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : isXhr=true (XHR 방식) ──");
        scwin.patchXhr();
        $p.download("/data/$p_download_sample.txt", "K00001", "post", true);

        $p.setTimeout(function () {
            var cap = scwin.xhrCaptured;
            if (cap && cap.method !== null) {
                wf_body_bottom.getObj("scwin").setReturnValue("XHR method : '" + String(cap.method).toUpperCase() + "' / url : '" + cap.url + "'");

                var hasCT = false;
                var ctVal = "";
                for (var i = 0; i < cap.headers.length; i++) {
                    var h = cap.headers[i];
                    if (String(h.name).toLowerCase() === "content-type") {
                        hasCT = true;
                        ctVal = h.value;
                        break;
                    }
                }
                wf_body_bottom.getObj("scwin").setReturnValue("Content-Type 설정 여부 : " + (hasCT ? ctVal : "(미설정)"));

                var bodyStr = "";
                if (cap.body !== null && cap.body !== undefined) {
                    bodyStr = String(cap.body);
                }
                wf_body_bottom.getObj("scwin").setReturnValue("body 에 K00001 포함 여부 : " + (bodyStr.indexOf("K00001") !== -1));
            } else {
                wf_body_bottom.getObj("scwin").setReturnValue("XHR 호출 미캡처");
            }
            scwin.restoreXhr();
        }, "chk_download_4", 300);
    }
};
